arguments.new_string:
def verification_feedback(verifier_output: str) -> str | None:
    verified_at = verifier_output.rfind(VERIFIED_SENTINEL)
    incomplete_at = verifier_output.rfind(INCOMPLETE_SENTINEL)
    if verified_at >= 0 and verified_at > incomplete_at:
        return None
    return verifier_output[-FEEDBACK_TAIL_CHARACTERS:]


def task_feedback_for(state: RalphState, task: str) -> str | None:
    if state["feedback_task"] == task:
        return state["feedback"]
    return None


def record_verdict(state: RalphState, task: str, verdict: str | None) -> None:
    if verdict is None:
        state["feedback"] = None
        state["feedback_task"] = None
        state["failed_attempts"] = 0
        return
    same_task = state["feedback_task"] == task
    state["failed_attempts"] = state["failed_attempts"] + 1 if same_task else 1
    state["feedback"] = verdict
    state["feedback_task"] = task


def run_backpressure_checks() -> str | None:
    for command in BACKPRESSURE_COMMANDS:
        result = subprocess.run(
            command, cwd=REPO_ROOT, capture_output=True, text=True
        )
        if result.returncode != 0:
            combined = result.stdout + result.stderr
            return (
                f"{INCOMPLETE_SENTINEL}: `{' '.join(command)}` failed after your "
                f"changes; fix this before anything else:\n"
                f"{combined[-FEEDBACK_TAIL_CHARACTERS:]}"
            )
    return None
